dashboard.definition:
{
  "title": "OpenBao token and lease lifecycle",
  "description": "OpenBao token and lease lifecycle. Native SPL operator-question bindings. Read panel descriptions for windows, missing data, and required external sources. See the profile validation record for tested environments and native alert coverage.",
  "inputs": {
    "input_cluster": {
      "type": "input.text",
      "title": "cluster (wildcard)",
      "options": {
        "token": "cluster",
        "defaultValue": "compose"
      }
    },
    "input_host": {
      "type": "input.text",
      "title": "host (wildcard)",
      "options": {
        "token": "host",
        "defaultValue": "*"
      }
    },
    "input_instance": {
      "type": "input.text",
      "title": "instance (wildcard)",
      "options": {
        "token": "instance",
        "defaultValue": "*"
      }
    },
    "input_kubernetes_namespace": {
      "type": "input.text",
      "title": "kubernetes namespace (wildcard)",
      "options": {
        "token": "kubernetes_namespace",
        "defaultValue": "*"
      }
    },
    "input_logical_namespace": {
      "type": "input.text",
      "title": "logical namespace (wildcard)",
      "options": {
        "token": "logical_namespace",
        "defaultValue": "*"
      }
    },
    "input_openbao_namespace": {
      "type": "input.text",
      "title": "openbao namespace (wildcard)",
      "options": {
        "token": "openbao_namespace",
        "defaultValue": "*"
      }
    },
    "input_operation": {
      "type": "input.text",
      "title": "operation (wildcard)",
      "options": {
        "token": "operation",
        "defaultValue": "*"
      }
    },
    "input_request_id": {
      "type": "input.text",
      "title": "request id (wildcard)",
      "options": {
        "token": "request_id",
        "defaultValue": "*"
      }
    },
    "input_request_path": {
      "type": "input.text",
      "title": "request path (wildcard)",
      "options": {
        "token": "request_path",
        "defaultValue": "*"
      }
    },
    "input_scrape_profile": {
      "type": "input.text",
      "title": "scrape profile (wildcard)",
      "options": {
        "token": "scrape_profile",
        "defaultValue": "all_nodes"
      }
    },
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-1h@h,now"
      }
    }
  },
  "dataSources": {
    "ds_expiration_backlog_change": {
      "type": "ds.search",
      "name": "Net expiration backlog change",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_*\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_core_active\" OR metric_name=\"vault_expire_job_manager_total_jobs\"\n| `openbao_metric_active_expiration`\n| `openbao_metric_slope5m`\n| eval series=cluster.\" / \".scrape_profile.\" / \".instance\n| timechart span=15s latest(value) BY series limit=0 useother=f",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_expiration_dispatch_wait": {
      "type": "ds.search",
      "name": "Dispatched expiration job wait",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_expire_lease_expiration_time_in_queue*\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where match(metric_name,\"_(sum|count)$\")\n| `openbao_metric_rate5m`\n| eval sum_rate=if(match(metric_name,\"_sum$\"),value,0), count_rate=if(match(metric_name,\"_count$\"),value,0)\n| stats sum(sum_rate) AS total sum(count_rate) AS events BY bucket_time cluster instance scrape_profile\n| where events\u003e0\n| eval value=total/events\n| rename bucket_time AS _time\n| eval series=cluster.\" / \".scrape_profile.\" / \".instance\n| timechart span=15s latest(value) BY series limit=0 useother=f",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_expiration_pending_jobs": {
      "type": "ds.search",
      "name": "Waiting expiration jobs",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_*\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_core_active\" OR metric_name=\"vault_expire_job_manager_total_jobs\"\n| `openbao_metric_active_expiration`\n| eval series=cluster.\" / \".scrape_profile.\" / \".instance\n| timechart span=15s latest(value) BY series limit=0 useother=f",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_expiration_queue_length": {
      "type": "ds.search",
      "name": "Waiting jobs by mount queue",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_*\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_core_active\" OR metric_name=\"vault_expire_job_manager_queue_length\"\n| `openbao_metric_active_expiration`\n| eval series=cluster.\" / \".scrape_profile.\" / \".instance.\" / \".queue_id\n| timechart span=15s latest(value) BY series limit=0 useother=f",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_filtered_token_lease_stream": {
      "type": "ds.search",
      "name": "Filtered token and lease stream",
      "options": {
        "query": "`openbao_audit_events`\n| search request_id=$request_id|s$ request_path=$request_path|s$ logical_namespace=$logical_namespace|s$ operation=$operation|s$ host=$host|s$\n| where match(request_path,\"^(auth/token/|sys/leases/)\")\n| sort 100 - _time\n| table _time host audit_type request_id logical_namespace request_path operation caller client_ip audit_error",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_irrevocable_leases": {
      "type": "ds.search",
      "name": "Irrevocable leases",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_expire_num_irrevocable_leases\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| `openbao_metric_fresh`\n| stats latest(value) AS value BY cluster instance scrape_profile\n| stats max(value) AS value BY cluster scrape_profile",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_lease_count": {
      "type": "ds.search",
      "name": "Lease count",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_expire_num_leases\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| `openbao_metric_fresh`\n| stats latest(value) AS value BY cluster instance scrape_profile\n| stats max(value) AS value BY cluster scrape_profile",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_lease_management_audit_events": {
      "type": "ds.search",
      "name": "Lease management audit events",
      "options": {
        "query": "`openbao_audit_events`\n| search request_id=$request_id|s$ request_path=$request_path|s$ logical_namespace=$logical_namespace|s$ operation=$operation|s$ host=$host|s$\n| where match(request_path,\"^sys/leases/\")\n| sort 100 - _time\n| table _time host audit_type request_id logical_namespace request_path operation caller client_ip audit_error",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_lease_operation_latency": {
      "type": "ds.search",
      "name": "Lease operation latency",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_expire_re*\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_expire_revoke_sum\" OR metric_name=\"vault_expire_revoke_count\" OR metric_name=\"vault_expire_register_auth_sum\" OR metric_name=\"vault_expire_register_auth_count\"\n| eval series=case(metric_name=\"vault_expire_revoke_sum\",\"revoke\",metric_name=\"vault_expire_revoke_count\",\"revoke\",metric_name=\"vault_expire_register_auth_sum\",\"register auth\",metric_name=\"vault_expire_register_auth_count\",\"register auth\") .\" | \".coalesce(openbao_namespace,\"(missing)\") .\" | \".cluster .\" | \".scrape_profile\n| `openbao_metric_rate5m`\n| stats sum(eval(if(match(metric_name,\"_sum$\"),value,null()))) AS total sum(eval(if(match(metric_name,\"_count$\"),value,null()))) AS observations BY bucket_time cluster scrape_profile series\n| where observations\u003e0\n| eval value=total/observations\n| eval _time=bucket_time\n| timechart span=15s max(value) BY series limit=20 useother=f cont=f",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_lease_revoke_rate": {
      "type": "ds.search",
      "name": "Lease revoke rate",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_expire_revoke_count\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| `openbao_metric_rate5m`\n| `openbao_metric_fresh`\n| stats sum(value) AS value BY bucket_time cluster scrape_profile\n| rename bucket_time AS _time\n| timechart span=15s latest(value) AS value",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_token_count": {
      "type": "ds.search",
      "name": "Token count",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_token_count\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_token_count\"\n| sort 0 _time\n| streamstats time_window=30m max(value) AS value BY _timeseries\n| eval series=openbao_namespace .\" | \".cluster .\" | \".scrape_profile\n| stats max(value) AS value BY bucket_time cluster scrape_profile series\n| eval _time=bucket_time\n| `openbao_metric_fresh`\n| stats latest(value) AS value BY cluster scrape_profile series\n| stats sum(value) AS value count AS contributing_series\n| where contributing_series\u003e0\n| fields - contributing_series",
        "queryParameters": {
          "earliest": "-30m",
          "latest": "now"
        }
      }
    },
    "ds_token_create_rate": {
      "type": "ds.search",
      "name": "Token create rate",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_token_create_count\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_token_create_count\"\n| eval series=case(metric_name=\"vault_token_create_count\",\"token_create\") .\" | \".coalesce(openbao_namespace,\"(missing)\") .\" | \".cluster .\" | \".scrape_profile\n| `openbao_metric_rate5m`\n| stats sum(value) AS value BY bucket_time cluster scrape_profile series\n| eval _time=bucket_time\n| `openbao_metric_fresh`\n| stats latest(value) AS value BY cluster scrape_profile series\n| stats sum(value) AS value count AS contributing_series\n| where contributing_series\u003e0\n| fields - contributing_series",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_token_creation_by_auth_method": {
      "type": "ds.search",
      "name": "Token creation by auth method",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_token_creation\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_token_creation\"\n| eval series=case(metric_name=\"vault_token_creation\",\"token_creation\") .\" | \".coalesce(auth_method,\"(missing)\") .\" | \".coalesce(openbao_namespace,\"(missing)\") .\" | \".cluster .\" | \".scrape_profile\n| `openbao_metric_rate15m`\n| eval value=value*900\n| stats sum(value) AS value BY bucket_time cluster scrape_profile series\n| eval _time=bucket_time\n| timechart span=15s max(value) BY series limit=20 useother=f cont=f",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_token_creations": {
      "type": "ds.search",
      "name": "Token creations",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_token_creation\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_token_creation\"\n| eval series=case(metric_name=\"vault_token_creation\",\"token_creation\") .\" | \".coalesce(openbao_namespace,\"(missing)\") .\" | \".cluster .\" | \".scrape_profile\n| `openbao_metric_rate15m`\n| eval value=value*900\n| stats sum(value) AS value BY bucket_time cluster scrape_profile series\n| eval _time=bucket_time\n| `openbao_metric_fresh`\n| stats latest(value) AS value BY cluster scrape_profile series\n| stats sum(value) AS value count AS contributing_series\n| where contributing_series\u003e0\n| fields - contributing_series",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_token_lease_inventory": {
      "type": "ds.search",
      "name": "Token and lease inventory",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_*\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_token_count\" OR metric_name=\"vault_expire_num_leases\" OR metric_name=\"vault_expire_num_irrevocable_leases\"\n| sort 0 _time\n| streamstats time_window=30m max(value) AS historical BY _timeseries\n| eval value=if(match(metric_name,\"_token_count$\"),historical,value), series=metric_name .\" | \".openbao_namespace .\" | \".cluster .\" | \".scrape_profile\n| stats max(value) AS value BY bucket_time cluster scrape_profile series\n| eval _time=bucket_time\n| timechart span=15s max(value) BY series limit=20 useother=f cont=f",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_token_lifecycle_audit_events": {
      "type": "ds.search",
      "name": "Token lifecycle audit events",
      "options": {
        "query": "`openbao_audit_events`\n| search request_id=$request_id|s$ request_path=$request_path|s$ logical_namespace=$logical_namespace|s$ operation=$operation|s$ host=$host|s$\n| where match(request_path,\"^auth/token/\")\n| sort 100 - _time\n| table _time host audit_type request_id logical_namespace request_path operation caller client_ip audit_error",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_token_lookup_rate": {
      "type": "ds.search",
      "name": "Token lookup rate",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_token_lookup_count\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_token_lookup_count\"\n| eval series=case(metric_name=\"vault_token_lookup_count\",\"token_lookup\") .\" | \".coalesce(openbao_namespace,\"(missing)\") .\" | \".cluster .\" | \".scrape_profile\n| `openbao_metric_rate5m`\n| stats sum(value) AS value BY bucket_time cluster scrape_profile series\n| eval _time=bucket_time\n| `openbao_metric_fresh`\n| stats latest(value) AS value BY cluster scrape_profile series\n| stats sum(value) AS value count AS contributing_series\n| where contributing_series\u003e0\n| fields - contributing_series",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_token_operation_latency": {
      "type": "ds.search",
      "name": "Token operation latency",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_token_*\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_token_create_sum\" OR metric_name=\"vault_token_create_count\" OR metric_name=\"vault_token_lookup_sum\" OR metric_name=\"vault_token_lookup_count\" OR metric_name=\"vault_token_store_sum\" OR metric_name=\"vault_token_store_count\" OR metric_name=\"vault_token_revoke_tree_sum\" OR metric_name=\"vault_token_revoke_tree_count\"\n| eval series=case(metric_name=\"vault_token_create_sum\",\"create\",metric_name=\"vault_token_create_count\",\"create\",metric_name=\"vault_token_lookup_sum\",\"lookup\",metric_name=\"vault_token_lookup_count\",\"lookup\",metric_name=\"vault_token_store_sum\",\"store\",metric_name=\"vault_token_store_count\",\"store\",metric_name=\"vault_token_revoke_tree_sum\",\"revoke tree\",metric_name=\"vault_token_revoke_tree_count\",\"revoke tree\") .\" | \".coalesce(openbao_namespace,\"(missing)\") .\" | \".cluster .\" | \".scrape_profile\n| `openbao_metric_rate5m`\n| stats sum(eval(if(match(metric_name,\"_sum$\"),value,null()))) AS total sum(eval(if(match(metric_name,\"_count$\"),value,null()))) AS observations BY bucket_time cluster scrape_profile series\n| where observations\u003e0\n| eval value=total/observations\n| eval _time=bucket_time\n| timechart span=15s max(value) BY series limit=20 useother=f cont=f",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_token_operation_rates": {
      "type": "ds.search",
      "name": "Token operation rates",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_token_*\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_token_create_count\" OR metric_name=\"vault_token_lookup_count\" OR metric_name=\"vault_token_store_count\" OR metric_name=\"vault_token_revoke_tree_count\"\n| eval series=case(metric_name=\"vault_token_create_count\",\"create\",metric_name=\"vault_token_lookup_count\",\"lookup\",metric_name=\"vault_token_store_count\",\"store\",metric_name=\"vault_token_revoke_tree_count\",\"revoke tree\") .\" | \".coalesce(openbao_namespace,\"(missing)\") .\" | \".cluster .\" | \".scrape_profile\n| `openbao_metric_rate5m`\n| stats sum(value) AS value BY bucket_time cluster scrape_profile series\n| eval _time=bucket_time\n| timechart span=15s max(value) BY series limit=20 useother=f cont=f",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_token_revoke_tree_rate": {
      "type": "ds.search",
      "name": "Token revoke-tree rate",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_token_revoke_tree_count\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_token_revoke_tree_count\"\n| eval series=case(metric_name=\"vault_token_revoke_tree_count\",\"token_revoke_tree\") .\" | \".coalesce(openbao_namespace,\"(missing)\") .\" | \".cluster .\" | \".scrape_profile\n| `openbao_metric_rate5m`\n| stats sum(value) AS value BY bucket_time cluster scrape_profile series\n| eval _time=bucket_time\n| `openbao_metric_fresh`\n| stats latest(value) AS value BY cluster scrape_profile series\n| stats sum(value) AS value count AS contributing_series\n| where contributing_series\u003e0\n| fields - contributing_series",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_token_store_rate": {
      "type": "ds.search",
      "name": "Token store rate",
      "options": {
        "query": "| `openbao_metric_samples(\"vault_token_store_count\")`\n| search cluster=$cluster|s$ instance=$instance|s$ scrape_profile=$scrape_profile|s$ kubernetes_namespace=$kubernetes_namespace|s$ openbao_namespace=$openbao_namespace|s$\n| where metric_name=\"vault_token_store_count\"\n| eval series=case(metric_name=\"vault_token_store_count\",\"token_store\") .\" | \".coalesce(openbao_namespace,\"(missing)\") .\" | \".cluster .\" | \".scrape_profile\n| `openbao_metric_rate5m`\n| stats sum(value) AS value BY bucket_time cluster scrape_profile series\n| eval _time=bucket_time\n| `openbao_metric_fresh`\n| stats latest(value) AS value BY cluster scrape_profile series\n| stats sum(value) AS value count AS contributing_series\n| where contributing_series\u003e0\n| fields - contributing_series",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    }
  },
  "visualizations": {
    "viz_expiration_backlog_change": {
      "type": "splunk.line",
      "title": "Net expiration backlog change",
      "description": "Rolling five-minute least-squares backlog slope in jobs per second per active target. Negative values indicate net drain; leader histories remain separate.",
      "dataSources": {
        "primary": "ds_expiration_backlog_change"
      },
      "options": {
        "yAxisTitleText": "operations/s"
      }
    },
    "viz_expiration_dispatch_wait": {
      "type": "splunk.line",
      "title": "Dispatched expiration job wait",
      "description": "Rolling five-minute mean wait for dispatched jobs, in milliseconds. This excludes jobs still waiting.",
      "dataSources": {
        "primary": "ds_expiration_dispatch_wait"
      },
      "options": {
        "yAxisTitleText": "ms"
      }
    },
    "viz_expiration_pending_jobs": {
      "type": "splunk.line",
      "title": "Waiting expiration jobs",
      "description": "Waiting expiration jobs on the active target only. Missing queue metrics remain absent.",
      "dataSources": {
        "primary": "ds_expiration_pending_jobs"
      }
    },
    "viz_expiration_queue_length": {
      "type": "splunk.line",
      "title": "Waiting jobs by mount queue",
      "description": "Waiting jobs by mount queue on the active target. A queue ID identifies a mount, not a consumer.",
      "dataSources": {
        "primary": "ds_expiration_queue_length"
      }
    },
    "viz_filtered_token_lease_stream": {
